insert into public.site_content (collection,slug,title,data,published,position)
values
('aeo_keywords','how-ai-helps-business','How can AI software help my business?',jsonb_build_object('answer','AI software can assist with repetitive processes, customer questions, search, document handling, and product workflows. The best use depends on your process, data, risk, and need for human review. Start with a small measurable pilot.','related_questions','What business processes can AI automate?,How do I start an AI project?','target_page','/services'),true,0),
('aeo_keywords','ai-ecommerce-discovery','How can AI improve product discovery in an online store?',jsonb_build_object('answer','AI can support conversational search and relevant product recommendations when catalogue data is accurate. Keep suggestions easy to refine, protect customer information, and measure whether shoppers find useful products.','related_questions','Can AI recommend products to shoppers?,What data does ecommerce AI need?','target_page','/blogs/ai-in-ecommerce-product-discovery'),true,1),
('aeo_keywords','company-information-ai','How can an AI assistant answer using my company information?',jsonb_build_object('answer','Connect the assistant to approved, current company material and test it with real questions and edge cases. Retrieval can provide source context; fine-tuning may help with repeatable task behavior. Add access controls and human escalation.','related_questions','Should I fine-tune a model on company documents?,How do I keep business AI answers current?','target_page','/blogs/business-ai-finetuning-company-knowledge'),true,2),
('aeo_keywords','which-workflows-ai','Which business workflows are suitable for AI automation?',jsonb_build_object('answer','Workflows involving unstructured text, documents, classification, or drafting may benefit from AI assistance. Use ordinary rules for predictable decisions, and retain approval steps for exceptions or consequential actions.','related_questions','Which tasks should not be automated with AI?,How can I pilot AI automation safely?','target_page','/blogs/ai-workflow-automation-business'),true,3),
('aeo_keywords','ai-digital-marketing-uses','How can businesses use AI in digital marketing?',jsonb_build_object('answer','Teams can use AI to cluster search questions, draft content outlines, create campaign variants, and summarize reports. People should verify facts, preserve brand voice, and approve public content.','related_questions','Can AI help with SEO?,How should AI-generated marketing content be reviewed?','target_page','/blogs/ai-digital-marketing-content-operations'),true,4),
('aeo_keywords','mobile-ai-features','What are useful AI features for a mobile app?',jsonb_build_object('answer','Useful patterns include natural-language assistance, speech transcription, image understanding, and personalized discovery. Choose features that solve a user need and plan for privacy, connectivity, accessibility, and failure states.','related_questions','Can mobile AI work offline?,How do I protect app users data?','target_page','/blogs/ai-mobile-app-development-use-cases'),true,5),
('aeo_keywords','ai-product-steps','What are the steps to develop an AI software product?',jsonb_build_object('answer','Define a user problem and success measure, check data readiness, prototype, evaluate edge cases, and plan security and monitoring. Launch narrowly, collect feedback, and improve with clear product ownership.','related_questions','How long does AI product development take?,What should an AI pilot measure?','target_page','/blogs/ai-software-product-development-lifecycle'),true,6),
('aeo_keywords','trustworthy-ai-product-design','How should an AI product be designed for user trust?',jsonb_build_object('answer','Explain what the AI does, show uncertainty in understandable ways, let people correct outputs, and provide human review for consequential tasks. Test the complete experience with intended users.','related_questions','How should AI uncertainty be shown?,When should AI decisions require human review?','target_page','/blogs/ai-product-design-human-centered'),true,7),
('aeo_keywords','accurate-support-ai','How do you keep an AI customer support assistant accurate?',jsonb_build_object('answer','Ground answers in approved current help content, test common and difficult questions, monitor unresolved cases, and offer a human handoff. Update source articles when staff identify gaps.','related_questions','Should a support chatbot cite sources?,When should a support assistant hand off to a person?','target_page','/blogs/ai-customer-support-assistant-grounding'),true,8),
('aeo_keywords','ai-integrate-existing-software','How can AI be integrated with existing business software?',jsonb_build_object('answer','Map data flows and permissions, connect through secure server-side integrations, and start with read-only assistance. Add actions gradually with validation, confirmation, logging, and a manual fallback.','related_questions','Can AI connect to a CRM or inventory system?,How do I keep AI integrations secure?','target_page','/blogs/ai-web-applications-business-integrations'),true,9)
