-- Give the illustrative personas a consistent before / AI-enabled / after story.
update public.site_content as content
set data = content.data || jsonb_build_object(
  'story_before', story.before_text,
  'story_solution', story.ai_text,
  'story_difference', story.after_text,
  'story_tag', 'Before → AI-enabled',
  'image_url', story.image_url,
  'image_alt', story.image_alt
), updated_at = now()
from (values
('sample-ecommerce-storefront','The catalogue had grown, but shoppers mostly relied on fixed filters and manually curated category pages.','An AI-assisted search experience interprets plain-language needs and suggests relevant products from verified catalogue details.','The journey becomes more conversational and easier to explore, while shoppers still control filters and final choices.','https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1100&q=80','Illustrative ecommerce team reviewing an online shopping experience'),
('sample-ai-product-discovery','Customers had to know the exact product name or browse many categories to find a suitable option.','A semantic discovery layer understands intent and helps narrow choices using catalogue attributes and clear recommendations.','Product discovery can feel more helpful and natural, without pretending recommendations are guaranteed or replacing customer judgment.','https://images.unsplash.com/photo-1556740738-b6a63e27c4df?auto=format&fit=crop&w=1100&q=80','Illustrative online marketplace shopping experience'),
('sample-business-ai-finetuning','Staff searched across documents and repeated the same internal questions, with answers depending on who was available.','A company knowledge assistant retrieves from approved material, provides context, and escalates unclear or restricted requests.','Teams get a faster starting point for routine questions while source ownership, access controls, and human decisions remain in place.','https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1100&q=80','Illustrative team collaborating around a business knowledge assistant'),
('sample-digital-marketing-plan','Planning research, content drafts, and reporting were spread across manual tasks and disconnected documents.','AI helps cluster customer questions, prepare draft outlines, and summarize reporting for human review and approval.','The workflow becomes more organized and easier to repeat, while strategy, fact checking, and publishing stay with the marketing team.','https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1100&q=80','Illustrative marketing team planning an AI-assisted content workflow'),
('sample-mobile-app-field-work','Field staff entered updates after visits and manually converted notes into follow-up tasks back at the office.','An AI-enabled mobile app can structure voice or typed notes into draft summaries and suggested follow-ups for staff confirmation.','Updates can move into the workflow sooner, with staff reviewing every summary before it is saved or shared.','https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1100&q=80','Illustrative field team using a mobile work application'),
('sample-product-discovery-development','The product idea was broad, and the team found it hard to agree on the first useful release and where AI belonged.','Product discovery maps user needs, prototypes AI and non-AI options, and evaluates likely failure cases before implementation.','The team can make a more informed first-release decision and test whether AI improves the user journey before investing further.','https://images.unsplash.com/photo-1553877522-43269d4ea984?auto=format&fit=crop&w=1100&q=80','Illustrative product team reviewing a software prototype'),
('sample-user-experience-design','People encountered AI suggestions without enough context to know why they appeared or how to correct them.','The interface explains AI assistance, makes suggestions editable, and offers a clear route to complete the task without AI.','AI becomes a visible aid within the product experience, with user choice and correction built into the interaction.','https://images.unsplash.com/photo-1559028006-448665bd7c7f?auto=format&fit=crop&w=1100&q=80','Illustrative designers reviewing an AI product interface'),
('sample-workflow-automation','A repetitive intake process required staff to read each request and manually route it to the right team.','AI classifies and summarizes incoming requests, while business rules and staff approval handle routing exceptions.','Routine requests get a structured first pass, and people retain oversight for ambiguous or sensitive cases.','https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1100&q=80','Illustrative operations team reviewing an automated workflow'),
('sample-web-platform-integration','Useful business information sat in separate systems, so staff switched tools and copied details between screens.','A secure AI web application brings approved information into one workflow and asks for confirmation before taking actions.','The workflow can reduce context switching and make information easier to use, while permissions and confirmation protect important actions.','https://images.unsplash.com/photo-1551434678-e076c223a692?auto=format&fit=crop&w=1100&q=80','Illustrative software team building a connected business application'),
('sample-ai-support-assistant','Support staff answered recurring questions manually and customers sometimes struggled to find the right help article.','An AI support assistant answers from approved help content, links users to next steps, and hands uncertain cases to a person.','Customers get a clearer first step at any time, and support staff remain available for complex or sensitive issues.','https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&w=1100&q=80','Illustrative customer support team designing an AI assistant')
) as story(slug,before_text,ai_text,after_text,image_url,image_alt)
where content.collection='testimonials' and content.slug=story.slug and content.data->>'is_sample'='true';

update public.site_content as content
set data = content.data || jsonb_build_object('image_url', image.image_url, 'image_alt', image.image_alt), updated_at = now()
from (values
('ai-in-ecommerce-product-discovery','https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?auto=format&fit=crop&w=1100&q=80','Illustrative online store and ecommerce experience'),
('business-ai-finetuning-company-knowledge','https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1100&q=80','Illustrative business team working with company knowledge'),
('ai-workflow-automation-business','https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1100&q=80','Illustrative team reviewing a business automation workflow'),
('ai-digital-marketing-content-operations','https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1100&q=80','Illustrative marketing team planning content'),
('ai-mobile-app-development-use-cases','https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1100&q=80','Illustrative team using a mobile business app'),
('ai-software-product-development-lifecycle','https://images.unsplash.com/photo-1553877522-43269d4ea984?auto=format&fit=crop&w=1100&q=80','Illustrative software product team planning a release'),
('ai-product-design-human-centered','https://images.unsplash.com/photo-1559028006-448665bd7c7f?auto=format&fit=crop&w=1100&q=80','Illustrative product designers reviewing an interface'),
('ai-customer-support-assistant-grounding','https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&w=1100&q=80','Illustrative customer support team'),
('ai-web-applications-business-integrations','https://images.unsplash.com/photo-1551434678-e076c223a692?auto=format&fit=crop&w=1100&q=80','Illustrative software team building an integrated web app'),
('choose-ai-or-rules-based-automation','https://images.unsplash.com/photo-1556761175-b413da4baf72?auto=format&fit=crop&w=1100&q=80','Illustrative business team comparing workflow options')
) as image(slug,image_url,image_alt)
where content.collection='blogs' and content.slug=image.slug;
